
import uuid

import pytest


def test_complete_candidate_registration(client, monkeypatch):
    """
    Test the complete candidate registration flow:

    1. Send OTP
    2. Verify OTP
    3. Obtain verification ticket
    4. Register candidate

    Gmail SMTP is mocked to avoid sending real emails.
    """

    # Capture the OTP generated by the actual OTP service.
    captured = {}

    def mock_send_otp_email(email: str, otp: str) -> None:
        captured["email"] = email
        captured["otp"] = otp

    monkeypatch.setattr(
        "app.services.email.otp_service.send_otp_email",
        mock_send_otp_email,
    )

    email = f"candidate_{uuid.uuid4().hex[:10]}@gmail.com"

    # --------------------------------------------------
    # STEP 1: Send OTP
    # --------------------------------------------------

    send_response = client.post(
        "/api/v1/auth/otp/send",
        json={
            "email": email,
            "purpose": "CANDIDATE_REGISTRATION",
        },
    )

    assert send_response.status_code == 200
    assert captured["email"] == email
    assert "otp" in captured

    # --------------------------------------------------
    # STEP 2: Verify OTP
    # --------------------------------------------------

    verify_response = client.post(
        "/api/v1/auth/otp/verify",
        json={
            "email": email,
            "purpose": "CANDIDATE_REGISTRATION",
            "otp": captured["otp"],
        },
    )

    assert verify_response.status_code == 200

    verify_data = verify_response.json()

    assert verify_data.get("verification_ticket")

    ticket = verify_data["verification_ticket"]

    # --------------------------------------------------
    # STEP 3: Register Candidate
    # --------------------------------------------------

    registration_response = client.post(
        "/api/v1/auth/candidate/register",
        json={
            "full_name": "Test Candidate",
            "email": email,
            "password": "NexAbilityTest@12345",
            "phone": None,
            "verification_ticket": ticket,
        },
    )

    assert registration_response.status_code in (200, 201)

    registration_data = registration_response.json()

    assert registration_data is not None

    # --------------------------------------------------
    # STEP 4: Confirm successful registration
    # --------------------------------------------------

    assert registration_response.status_code in (200, 201)

    print(f"Candidate registered successfully: {email}")
